      es: "La mayor colonia de cría de pingüinos de Magallanes en el continente sudamericano con cientos de miles de animales.",
      pt: "A maior colônia de reprodução de pinguins-de-magalhães no continente sul-americano, com centenas de milhares de animais.",
      fr: "La plus grande colonie de reproduction de manchots de Magellan sur le continent sud-américain avec des centaines de milliers d'animaux.",
