      es: ["Aquí viven más de 4.000 lobos marinos.", "Ofrece buenos puntos de observación.", "Las orcas también cazan cerca.", "Una importante zona de investigación."],
      pt: ["Mais de 4.000 leões-marinhos vivem aqui.", "Oferece bons pontos de observação.", "Orcas também caçam nas proximidades.", "Uma área de pesquisa importante."],
