      es: ["Una de las principales zonas de cultivo de tabaco.", "Muchos secaderos tradicionales.", "La cosecha suele ser manual.", "El paisaje es muy verde."],
      pt: ["Uma das principais zonas de cultivo de tabaco.", "Muitos secadores tradicionais.", "A colheita costuma ser manual.", "A paisagem é muito verde."],
