    descriptionAdvanced: {
        hu: "A Bodega Colomé a saltai Calchaquí-völgyben Argentína egyik legrégebbi és legmagasabban fekvő pincészete. Az 1831-ben alapított pincészet szőlőültetvényei akár 3111 méteres magasságban is megtalálhatók, ami a világ legmagasabbjai közé teszi. Ezek a szélsőséges körülmények, a száraz éghajlattal és az intenzív napsütéssel kombinálva, nagy koncentrációjú, összetett és elegáns borokat eredményeznek, különösen Malbecet és Torrontést. A pincészet otthont ad a James Turrell Múzeumnak is, amelyet ennek az amerikai fény- és térművésznek a munkásságának szenteltek, és egyedülálló érzékszervi élményt nyújt. A Colomé egy távoli és exkluzív célpont, amely ötvözi az andoki táj fenségét a világszínvonalú borok és az avantgárd művészet kifinomultságával.",
      de: "Die Bodega Colomé in den Calchaquí-Tälern von Salta ist eines der ältesten und höchstgelegenen Weingüter Argentiniens. Gegründet 1831, verfügt es über Weinberge auf Höhen von bis zu 3.111 Metern, was es zu einem der höchsten der Welt macht. Diese extremen Bedingungen, kombiniert mit dem trockenen Klima und der intensiven Sonneneinstrahlung, ergeben Weine von großer Konzentration, Komplexität und Eleganz, insbesondere Malbec und Torrontés. Das Weingut beherbergt auch das James-Turrell-Museum, das dem Werk dieses amerikanischen Licht- und Raumkünstlers gewidmet ist und ein einzigartiges Sinneserlebnis bietet. Colomé ist ein abgelegenes und exklusives Reiseziel, das die Erhabenheit der Andenlandschaft mit der Raffinesse von Weltklasse-Weinen und avantgardistischer Kunst verbindet.",
      ro: "Bodega Colomé, din Văile Calchaquí din Salta, este una dintre cele mai vechi și mai înalte crame din Argentina. Fondată în 1831, are podgorii la altitudini de până la 3.111 metri, ceea ce o face una dintre cele mai înalte din lume. Aceste condiții extreme, combinate cu clima uscată și soarele intens, produc vinuri de o mare concentrație, complexitate și eleganță, în special Malbec și Torrontés. Crama găzduiește, de asemenea, Muzeul James Turrell, dedicat operei acestui artist american al luminii și spațiului, oferind o experiență senzorială unică. Colomé este o destinație îndepărtată și exclusivistă, care combină măreția peisajului andin cu rafinamentul vinurilor de clasă mondială și al artei avangardiste.",
      en: "Bodega Colomé, in the Calchaquí Valleys of Salta, is one of the oldest and highest wineries in Argentina. Founded in 1831, it has vineyards at altitudes of up to 3,111 meters, making it one of the highest in the world. These extreme conditions, combined with the dry climate and intense sun, produce wines of great concentration, complexity, and elegance, especially Malbec and Torrontés. The winery also houses the James Turrell Museum, dedicated to the work of this American light and space artist, offering a unique sensory experience. Colomé is a remote and exclusive destination that combines the grandeur of the Andean landscape with the sophistication of world-class wines and avant-garde art.",
        es: "La Bodega Colomé, situada en los Valles Calchaquíes de Salta, es una de las bodegas más antiguas y elevadas de Argentina. Fundada en 1831, cuenta con viñedos situados a altitudes de hasta 3.111 metros, lo que los convierte en unos de los más altos del mundo. Estas condiciones extremas, combinadas con el clima seco y la intensa radiación solar, dan como resultado vinos de gran concentración, complejidad y elegancia, especialmente Malbec y Torrontés. La bodega también alberga el Museo James Turrell, dedicado a la obra de este artista estadounidense de la luz y el espacio, que ofrece una experiencia sensorial única. Colomé es un destino remoto y exclusivo que combina la grandeza del paisaje andino con la sofisticación de vinos de clase mundial y arte de vanguardia.",
        pt: "A Bodega Colomé, nos Vales Calchaquíes de Salta, é uma das vinícolas mais antigas e mais altas da Argentina. Fundada em 1831, possui vinhedos em altitudes de até 3.111 metros, o que os torna alguns dos mais altos do mundo. Estas condições extremas, combinadas com o clima seco e a radiação solar intensa, resultam em vinhos de grande concentração, complexidade e elegância, especialmente Malbec e Torrontés. A vinícola também abriga o Museu James Turrell, dedicado ao trabalho deste artista americano de luz e espaço, oferecendo uma experiência sensorial única. Colomé é um destino remoto e exclusivo que combina a grandiosidade da paisagem andina com a sofisticação de vinhos de classe mundial e arte vanguardista.",
        fr: "La Bodega Colomé, située dans les vallées Calchaquíes de Salta, est l'un des domaines viticoles les plus anciens et les plus hauts d'Argentine. Fondé en 1831, il possède des vignobles situés à des altitudes allant jusqu'à 3 111 mètres, ce qui en fait l'un des plus élevés au monde. Ces conditions extrêmes, combinées au climat sec et à l'ensoleillement intense, produisent des vins d'une grande concentration, complexité et élégance, particulièrement le Malbec et le Torrontés. Le domaine abrite également le musée James Turrell, dédié à l'œuvre de cet artiste américain de la lumière et de l'espace, offrant une expérience sensorielle unique. Colomé est une destination isolée et exclusive qui allie la majesté du paysage andin au raffinement de vins de classe mondiale et d'art avant-gardiste.",
    },
